   433→
   434→          // 8각 별/다이아몬드
   435→          gfx.fillStyle(col, a);
   436→          gfx.fillPoints([
   437→            { x:  0,       y: -s      }, { x:  s * 0.4,  y: -s * 0.4 },
   438→            { x:  s,       y:  0      }, { x:  s * 0.4,  y:  s * 0.4 },
   439→            { x:  0,       y:  s      }, { x: -s * 0.4,  y:  s * 0.4 },
   440→            { x: -s,       y:  0      }, { x: -s * 0.4,  y: -s * 0.4 },
   441→          ], true);
   442→
   443→          // 중심 하이라이트
   444→          gfx.fillStyle(0xffffff, 0.50);
