    18→  readonly scene: Phaser.Scene;
    19→
    20→  updateScore(amount: number): void;
    21→  spawnGoldPoop(): void;
    22→  spawnDiamondPoop(): void;
    23→  spawnTopazPoop(): void;
    24→  spawnRainbowPoop(): void;
    25→  /** 특수 똥 수집 전체 처리 (카운트++, 점수, 획득 텍스트) */
    26→  collectGoldPoop(poop: Phaser.Physics.Arcade.Sprite): void;
    27→  collectDiamondPoop(poop: Phaser.Physics.Arcade.Sprite): void;
    28→  collectTopazPoop(poop: Phaser.Physics.Arcade.Sprite): void;
