    38→  onCreate(api: GameSceneAPI): void;
    39→
    40→  /** 플레이어 속도 보너스 (Player 생성 전 GameScene에서 읽음) */
    41→  getPlayerSpeedBonus(): number;
    42→
    43→  /** update() 점수 계산: base(보통 1)를 받아 실제 추가할 점수 반환 */
    44→  getTickScore(base: number): number;
    45→
    46→  /** 금·다이아·토파즈 스폰 점수 간격 (noise는 단축) */
    47→  getSpawnIntervals(): { gold: number; diamond: number; topaz: number };
    48→
    49→  /** checkMissedSpawnPoints 루프에서 매 점수마다 호출 */
    50→  onScoreMilestone(score: number, api: GameSceneAPI): void;
    51→
    52→  /** 특수 똥 수집 시 추가 보너스 점수 반환 (없으면 0) */
    53→  onCollectSpecial(type: SpecialPoopType): number;
    54→
